import { Directory, File, Paths } from "expo-file-system"

import { globToRegExp, normalizeRelative } from "../../lib/phone/sandbox"

// A workspace is a folder in the app's private storage. Nothing outside it is
// ever touched: every tool path is normalized and rejected if it escapes.
const ROOT = new Directory(Paths.document, "workspaces")

// Session ids are generated by us, but sanitize anyway so a bad id can never
// introduce path separators.
function safeId(id: string): string {
  return id.replace(/[^a-zA-Z0-9_-]/g, "_")
}

export function workspaceRoot(sessionID: string): Directory {
  const dir = new Directory(ROOT, safeId(sessionID))
  if (!dir.exists) dir.create({ intermediates: true, idempotent: true })
  return dir
}

export function resolveDirectory(sessionID: string, relative = ""): Directory {
  const rel = normalizeRelative(relative)
  const root = workspaceRoot(sessionID)
  if (!rel) return root
  return new Directory(root, ...rel.split("/"))
}

export function resolveFile(sessionID: string, relative: string): File {
  const rel = normalizeRelative(relative)
  if (!rel) throw new Error("Expected a file path, got the workspace root")
  const segments = rel.split("/")
  const name = segments.pop() as string
  const parent = resolveDirectory(sessionID, segments.join("/"))
  return new File(parent, name)
}

export async function readText(sessionID: string, relative: string): Promise<string> {
  const file = resolveFile(sessionID, relative)
  if (!file.exists) throw new Error(`No such file: ${relative}`)
  return file.text()
}

export function writeText(sessionID: string, relative: string, content: string): void {
  const segments = normalizeRelative(relative).split("/")
  const name = segments.pop()
  if (!name) throw new Error("Expected a file path, got the workspace root")
  const parent = resolveDirectory(sessionID, segments.join("/"))
  if (!parent.exists) parent.create({ intermediates: true, idempotent: true })
  const file = new File(parent, name)
  if (!file.exists) file.create({ intermediates: true, overwrite: true })
  file.write(content)
}

export interface WalkEntry {
  path: string
  isDirectory: boolean
  size: number | null
}

// Depth-first walk with a hard cap: a phone should never try to enumerate
// 50k node_modules entries in one tool call.
export function walk(sessionID: string, relative = "", maxEntries = 2000): WalkEntry[] {
  const start = resolveDirectory(sessionID, relative)
  const prefix = normalizeRelative(relative)
  const out: WalkEntry[] = []

  const visit = (dir: Directory) => {
    if (out.length >= maxEntries) return
    for (const entry of dir.list()) {
      if (out.length >= maxEntries) return
      const path = prefix ? `${prefix}/${relativeOf(entry.uri, start.uri)}` : relativeOf(entry.uri, start.uri)
      if (entry instanceof Directory) {
        out.push({ path, isDirectory: true, size: null })
        visit(entry)
        continue
      }
      out.push({ path, isDirectory: false, size: entry.size ?? null })
    }
  }

  visit(start)
  return out
}

function relativeOf(uri: string, rootUri: string): string {
  const base = rootUri.replace(/\/+$/, "")
  const decoded = decodeURIComponent(uri)
  const rootDecoded = decodeURIComponent(base)
  const trimmed = decoded.startsWith(`${rootDecoded}/`) ? decoded.slice(rootDecoded.length + 1) : decoded
  return trimmed
}

export function findFiles(sessionID: string, pattern: string, relative = "", maxEntries = 500): string[] {
  const matcher = globToRegExp(pattern)
  return walk(sessionID, relative, 4000)
    .filter((entry) => !entry.isDirectory && matcher.test(entry.path))
    .slice(0, maxEntries)
    .map((entry) => entry.path)
}

export interface GrepHit {
  path: string
  line: number
  text: string
}

const TEXT_EXTENSIONS = /\.(ts|tsx|js|jsx|mjs|cjs|json|md|txt|yml|yaml|toml|ini|cfg|css|html|xml|kt|java|swift|py|rb|go|rs|c|h|cpp|hpp|sh|ps1|sql|gradle|properties)$/i

export async function grep(
  sessionID: string,
  pattern: string,
  options: { path?: string; include?: string; maxHits?: number } = {},
): Promise<GrepHit[]> {
  const maxHits = options.maxHits ?? 200
  const matcher = new RegExp(pattern, "i")
  const include = options.include ? globToRegExp(options.include) : null
  const files = walk(sessionID, options.path ?? "", 4000)
    .filter((entry) => !entry.isDirectory)
    .filter((entry) => !include || include.test(entry.path))
    .slice(0, 500)

  const hits: GrepHit[] = []
  for (const file of files) {
    if (hits.length >= maxHits) break
    // Skip obvious binaries: they are noise, and on a phone they are also slow.
    const looksText = TEXT_EXTENSIONS.test(file.path) || !file.path.includes(".")
    if (!looksText) continue
    let content: string
    try {
      content = await readText(sessionID, file.path)
    } catch {
      continue
    }
    const lines = content.split("\n")
    for (let i = 0; i < lines.length && hits.length < maxHits; i++) {
      if (matcher.test(lines[i])) hits.push({ path: file.path, line: i + 1, text: lines[i].slice(0, 400) })
    }
  }
  return hits
}

export function workspaceFileCount(sessionID: string): number {
  return walk(sessionID, "", 5000).filter((entry) => !entry.isDirectory).length
}
